import{_ as t,o as a,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-08-12","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-08-12","date":"2020-08-12T00:00:00.000Z","updated":"2020-08-13T00:00:00.000Z","tags":["Ceph","分布式存储","代码审查","性能测试","缓存管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-12.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-12.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-08-12.md"};function e(n,r,s,u,h,p){return a(),l("div",null,[...r[0]||(r[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>参会人员</strong>: 多名研发人员，包括Sam、Tremaine等。</li><li><strong>会议时间</strong>: 最近一周。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>结构测试与技术门槛测试</strong>:</p><ul><li>Tremaine进行了技术门槛测试和修复工作，发现并解决了Cremation启动时存储检测器发出警告的问题。</li><li>问题原因为使用阻塞API读取配置文件，已改为使用异步IO（Async IO）解决。</li></ul></li><li><p><strong>代码审查与PR更新</strong>:</p><ul><li>Tremaine将完成对Sam创建的PR的审查，并进行了相应的修改。</li><li>目前仍在处理omap3布局操作。</li></ul></li><li><p><strong>中断可处理的未来</strong>:</p><ul><li>替换了所有sister future为aerator future，并正在将中断逻辑嵌入到aero radio creator中。</li></ul></li><li><p><strong>性能回归测试</strong>:</p><ul><li>讨论了使用pet market进行性能回归测试，但数据尚未准备好。</li></ul></li><li><p><strong>子树管理与内存解决方案</strong>:</p><ul><li>实施并测试了带有子树管理的corporate tracking facility。</li><li>正在寻找将基于内存的解决方案转移到systole的方法。</li></ul></li><li><p><strong>异步own entry</strong>:</p><ul><li>开始处理异步own entry，并解决相关问题。</li></ul></li><li><p><strong>缓存驱逐</strong>:</p><ul><li>正在编写缓存层的缓存驱逐实现，首先需要编写脏块写出。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>配置文件读取</strong>: 从阻塞API改为异步IO。</li><li><strong>PR审查</strong>: Tremaine负责完成对Sam的PR的审查。</li><li><strong>中断逻辑</strong>: 将中断逻辑嵌入到aero radio creator中。</li><li><strong>缓存驱逐</strong>: 开始实施缓存驱逐逻辑，首先处理脏块写出。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>提交PR</strong>: 完成中断逻辑的嵌入后，提交PR。</li><li><strong>性能数据</strong>: 准备并发送性能回归测试的数据。</li><li><strong>缓存驱逐</strong>: 继续实施缓存驱逐逻辑，并考虑是否需要通知机制。</li><li><strong>异步own entry</strong>: 继续处理异步own entry，并解决相关问题。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li><strong>逻辑地址空间的使用</strong>: 讨论了逻辑地址空间的使用，指出当前用法简单，未来可能需要更复杂的策略。</li><li><strong>多核支持</strong>: 讨论了多核支持的问题，包括多进程和多线程的策略。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议涵盖了多个技术议题，包括代码审查、性能测试、缓存管理等，并制定了相应的行动计划。所有参与者将继续推进各自负责的任务，并保持沟通以解决可能出现的问题。</p>',13)])])}const _=t(i,[["render",e]]);export{d as __pageData,_ as default};
